"""Render a light dashboard from the current retrospective demo pipeline."""
import json,sys
from pathlib import Path
import numpy as np
import pandas as pd
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from headway.aspect import DISPLAY,MEANING,RECOMMENDATION,AspectPolicy,why
from headway.deferral import DEFAULT_HORIZONS,horizon_key
ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/"data"
OUT=ROOT/"ui/headway.html"

def _clean(v):
    return round(float(v),3) if v is not None and pd.notna(v) and np.isfinite(v) else None

def build_payload(df,policy):
    days=sorted(df.day.unique())
    assets=[]
    for aid,g in df.groupby("asset_id",sort=True):
        g=g.set_index("day").reindex(days)
        rows=[]
        last_aspect=-1
        for d,r in g.iterrows():
            state=r.get("prediction_state")
            if pd.isna(state): state="missing_observation"
            asp=int(r.aspect) if pd.notna(r.get("aspect")) else (last_aspect if last_aspect>0 else -1)
            last_aspect=asp
            raw=int(r.raw_aspect) if pd.notna(r.get("raw_aspect")) else -1
            rows.append({"aspect":asp,"raw":raw,"state":state,
                "margin":_clean(r.get("rul_lower")),"point":_clean(r.get("rul_point")),
                "hi":_clean(r.get("health_index_smooth")),"slope":_clean(r.get("health_index_slope")),
                "stability":r.get("decision_stability") if pd.notna(r.get("decision_stability")) else "n/a",
                "evidence":why(r),"windows":{str(int(h)):(r.get(horizon_key(h)) if pd.notna(r.get(horizon_key(h))) else "unknown") for h in DEFAULT_HORIZONS},
                "baseline":r.get("baseline_source") if pd.notna(r.get("baseline_source")) else "unavailable",
                "contributions":{c.removeprefix("contribution_"):_clean(r[c]) for c in df if c.startswith("contribution_")}})
        assets.append({"id":aid,"train":str(g.train_id.dropna().iloc[0]),"rows":rows})
    return {"days":[pd.Timestamp(d).strftime("%Y-%m-%d") for d in days],"assets":assets,
        "labels":DISPLAY,"rec":RECOMMENDATION,"meaning":MEANING,
        "thresholds":{"withdraw":policy.withdraw_days,"tonight":policy.tonight_days,"plan":policy.plan_days},
        "scope":"Synthetic retrospective demonstration. Model fitted on all demo fault labels; this replay is not a historical forecast."}

TEMPLATE = '<!doctype html>\n<html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Headway — Fleet decisions</title>\n<style>\n  /* ------------------------------------------------------------------ theme\n     Light is the default: this is read on a depot screen and in daylight as\n     often as at 01:00. Dark is kept because the product\'s working hours really\n     are 00:00-05:30, and the toggle costs one attribute.\n\n     The four aspects get FOUR distinct hues, not the two the real signalling\n     colours would give. On a real signal head, PLAN and TONIGHT are both\n     yellow and are told apart by the NUMBER of lamps lit. On a screen that\n     reads as "two ambers that look the same", which is exactly the wrong\n     ambiguity for the two most consequential states. So: distinct hue AND the\n     lamp count, belt and braces.\n  */\n  :root{\n    --ground:#F4F6F9; --panel:#FFFFFF; --panel2:#FAFBFC; --line:#DFE4EA;\n    --line-strong:#C4CCD6;\n    --text:#0E1621; --muted:#5A6675; --faint:#8A94A2;\n    /* Lamp colours are vivid (they are dots, they need to read at 9px);\n       text colours are darker so they clear 4.5:1 on white. Four separated\n       hues - gold, orange, red - because PLAN and TONIGHT are the two most\n       consequential states and must never be mistaken for each other. */\n    --green:#07794F; --green-lamp:#10B981; --green-bg:#E7F6F0;\n    --plan:#A16207;  --plan-lamp:#EAB308; --plan-bg:#FEF7E0;\n    --tonight:#C2410C; --tonight-lamp:#F97316; --tonight-bg:#FEEEE2;\n    --red:#B01212; --red-lamp:#EF4444; --red-bg:#FCEAEA;\n    --accent:#1D4ED8; --accent-bg:#EAF0FE;\n    --shadow:0 1px 2px rgba(16,24,40,.06), 0 1px 3px rgba(16,24,40,.04);\n    /* Playfair Display throughout; IBM Plex Mono retained ONLY for figures,\n       because margins, sigma values and dates line up in columns and a\n       proportional serif breaks that alignment. */\n    --disp:\'Playfair Display\',Georgia,\'Times New Roman\',serif;\n    --body:\'Playfair Display\',Georgia,\'Times New Roman\',serif;\n    --mono:\'IBM Plex Mono\',Consolas,monospace;\n  }\n  :root[data-theme="dark"]{\n    --ground:#0A0F1A; --panel:#101726; --panel2:#0D1420; --line:#1E2A3D;\n    --line-strong:#2C3A50;\n    --text:#E6EDF7; --muted:#96A3B8; --faint:#5F6C80;\n    --green:#34D399; --green-lamp:#34D399; --green-bg:#0E2A20;\n    --plan:#FACC15;  --plan-lamp:#FACC15; --plan-bg:#2B2210;\n    --tonight:#FB923C; --tonight-lamp:#FB923C; --tonight-bg:#2E1B0F;\n    --red:#F87171; --red-lamp:#F87171; --red-bg:#2C1416;\n    --accent:#8FB6E8; --accent-bg:#132033;\n    --shadow:none;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--ground);color:var(--text);font-family:var(--body);\n       font-size:16px;font-weight:500;line-height:1.6;padding:0 22px 90px}\n  .wrap{max-width:1240px;margin:0 auto}\n\n  /* Two-pane shell: a persistent selector on the left, one view at a time on\n     the right. Splitting the views keeps each screen answering ONE question -\n     what must I do tonight / how is the fleet / what is this door doing -\n     rather than asking the reader to scroll past two answers to reach a third. */\n  .app{display:grid;grid-template-columns:222px 1fr;gap:28px;align-items:start}\n  .side{position:sticky;top:0;padding:22px 0 26px;display:flex;flex-direction:column;gap:20px}\n  nav{display:flex;flex-direction:column;gap:3px}\n  .nav-item{display:flex;justify-content:space-between;align-items:center;gap:10px;\n            background:transparent;border:1px solid transparent;border-radius:8px;\n            padding:10px 12px;cursor:pointer;width:100%;text-align:left;\n            font-family:var(--body);font-size:15px;font-weight:500;color:var(--muted)}\n  .nav-item:hover{background:var(--panel)}\n  .nav-item[aria-current="page"]{background:var(--panel);border-color:var(--line);\n            color:var(--text);font-weight:700;box-shadow:var(--shadow)}\n  .nav-item:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n  .badge{font-family:var(--mono);font-size:11px;font-weight:600;color:var(--muted);\n         background:var(--panel2);border:1px solid var(--line);border-radius:999px;\n         padding:1px 8px;font-variant-numeric:tabular-nums}\n  .nav-item[aria-current="page"] .badge{border-color:var(--line-strong);color:var(--text)}\n  .badge.hot{color:var(--tonight);border-color:var(--tonight)}\n\n  .side .panelbox{background:var(--panel);border:1px solid var(--line);border-radius:9px;\n                  padding:13px 14px;box-shadow:var(--shadow)}\n  .side .datebig{font-family:var(--mono);font-size:16px;font-weight:600;\n                 font-variant-numeric:tabular-nums;display:block;margin-bottom:9px}\n  .side .row{display:flex;gap:7px;align-items:center;margin-top:9px}\n  .side input[type=range]{width:100%;accent-color:var(--tonight)}\n  main{padding-top:22px;min-height:70vh}\n  .view{display:none} .view.on{display:block}\n  @media(max-width:880px){\n    .app{grid-template-columns:1fr;gap:8px}\n    .side{position:static;padding-bottom:8px}\n    nav{flex-direction:row;flex-wrap:wrap}\n    .nav-item{width:auto}\n    main{padding-top:6px}\n  }\n\n  /* ---------------------------------------------------------------- header */\n  header{display:flex;flex-wrap:wrap;gap:18px;align-items:center;\n         justify-content:space-between;padding:22px 0 16px}\n  .brand{font-family:var(--disp);font-weight:700;font-size:25px;letter-spacing:.03em;\n         display:flex;align-items:baseline}\n  .brand .chev{color:var(--tonight);font-weight:500;font-size:.78em;margin:0 .05em}\n  /* In the 222px sidebar the tagline cannot sit beside the wordmark without\n     wrapping mid-phrase, so it takes its own line. Column direction would break\n     the WORDMARK across lines instead ("HEAD / <> / WAY"), so wrap plus a\n     full-width basis on the tagline is the right tool here. */\n  .brand{flex-wrap:wrap;align-items:baseline;row-gap:3px}\n  .brand small{flex:0 0 100%;font-family:var(--body);font-weight:500;font-size:10.5px;\n               color:var(--faint);margin-left:0;letter-spacing:.14em;\n               text-transform:uppercase;white-space:nowrap}\n  .tools{display:flex;gap:8px;align-items:center}\n  .btn{background:var(--panel);color:var(--text);border:1px solid var(--line);\n       font-family:var(--mono);font-size:12px;padding:6px 12px;cursor:pointer;\n       border-radius:6px;box-shadow:var(--shadow)}\n  .btn:hover{border-color:var(--line-strong)}\n  .btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n\n  /* Aspect glyph. SHAPE carries the severity as well as colour, so the four\n     states stay separable in greyscale, on a bad projector, or for a\n     colour-blind viewer:\n\n         ring  ->  half  ->  full  ->  octagon\n       monitor    plan     tonight    withdraw\n\n     The octagon is doing real work: it is the stop sign, and it means the one\n     state that takes a train out of service never has to be read twice. */\n  .ico.a0{color:var(--green-lamp)} .ico.a1{color:var(--plan-lamp)}\n  .ico.a2{color:var(--tonight-lamp)} .ico.a3{color:var(--red-lamp)}\n\n  /* ----------------------------------------------------------- filter chips */\n  .filters{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:6px}\n  .chip{display:flex;align-items:center;gap:8px;background:var(--panel);\n        border:1px solid var(--line);border-radius:999px;padding:6px 14px;cursor:pointer;\n        font-size:13px;box-shadow:var(--shadow)}\n  .chip .n{font-family:var(--mono);font-weight:600;font-variant-numeric:tabular-nums}\n  .chip .t{color:var(--muted);font-size:12px;letter-spacing:.04em;text-transform:uppercase}\n  .chip:hover{border-color:var(--line-strong)}\n  .chip[aria-pressed="true"]{border-color:var(--accent);background:var(--accent-bg)}\n  .chip:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n  .chip.c0 .n{color:var(--green)} .chip.c1 .n{color:var(--plan)}\n  .chip.c2 .n{color:var(--tonight)} .chip.c3 .n{color:var(--red)}\n\n  /* ------------------------------------------------------------- date strip */\n  .scrub{display:flex;align-items:center;gap:14px;background:var(--panel);\n         border:1px solid var(--line);border-radius:8px;padding:12px 16px;\n         margin:14px 0 4px;box-shadow:var(--shadow)}\n  .scrub label{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;\n               text-transform:uppercase;color:var(--faint);white-space:nowrap}\n  .scrub input[type=range]{flex:1;accent-color:var(--tonight);min-width:120px}\n  .scrub .date{font-family:var(--mono);font-size:15px;font-weight:600;\n               font-variant-numeric:tabular-nums;white-space:nowrap}\n\n  h2{font-family:var(--disp);font-weight:600;font-size:18px;letter-spacing:.02em;\n     margin:32px 0 3px}\n  .sub{color:var(--muted);font-size:14.5px;margin:0 0 14px}\n\n  /* ------------------------------------------------------------------ cards */\n  .cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:14px}\n  .acard{background:var(--panel);border:1px solid var(--line);border-radius:10px;\n         padding:0;overflow:hidden;box-shadow:var(--shadow)}\n  .acard.a1{border-color:var(--plan)} .acard.a2{border-color:var(--tonight)}\n  .acard.a3{border-color:var(--red)}\n  .acard .body{padding:15px 17px 16px}\n  .acard .top{display:flex;justify-content:space-between;align-items:center;gap:10px}\n  .acard .vwrap{display:flex;align-items:center;gap:10px}\n  .acard .verd{font-family:var(--disp);font-weight:700;font-size:15px;letter-spacing:.05em}\n  .a1 .verd{color:var(--plan)} .a2 .verd{color:var(--tonight)} .a3 .verd{color:var(--red)}\n  .acard .aid{font-family:var(--mono);font-size:11.5px;color:var(--muted)}\n  .acard .mean{color:var(--text);font-size:14.5px;margin:8px 0 12px}\n  .acard.held{border-color:var(--line)}\n  .acard.held .verd{color:var(--muted)}\n  .chip-held{font-family:var(--mono);font-size:9px;letter-spacing:.12em;font-weight:600;\n             border:1px solid var(--line-strong);color:var(--muted);padding:2px 7px;\n             border-radius:999px;margin-left:2px}\n\n  /* margin is the hero number - it is the thing being decided on */\n  .nums{display:flex;gap:10px;margin-bottom:11px}\n  .nums .cell{flex:1;background:var(--panel2);border:1px solid var(--line);\n              border-radius:7px;padding:8px 10px}\n  .nums .cell.hero{flex:1.25}\n  .k{font-family:var(--mono);font-size:9px;letter-spacing:.13em;\n     text-transform:uppercase;color:var(--faint);display:block;margin-bottom:2px}\n  .v{font-family:var(--mono);font-size:18px;font-weight:600;font-variant-numeric:tabular-nums;\n     line-height:1.2}\n  .v.sm{font-size:13px;font-weight:500}\n  .a1 .cell.hero .v{color:var(--plan)} .a2 .cell.hero .v{color:var(--tonight)}\n  .a3 .cell.hero .v{color:var(--red)}\n  .held .cell.hero .v{color:var(--muted)}\n  /* the deferral ledger: a priced menu, not a verdict */\n  .ledger{margin:2px 0 12px;border:1px solid var(--line);border-radius:7px;\n          background:var(--panel2);overflow:hidden}\n  .ledger .lhd{font-family:var(--mono);font-size:9px;letter-spacing:.13em;\n               text-transform:uppercase;color:var(--faint);padding:8px 11px 6px}\n  .ledger .lrow{display:flex;justify-content:space-between;align-items:baseline;\n                gap:10px;padding:4px 11px;font-size:13px}\n  .ledger .lrow:last-child{padding-bottom:9px}\n  .ledger .lrow .w{color:var(--muted)}\n  .ledger .lrow .p{font-family:var(--mono);font-weight:600;\n                   font-variant-numeric:tabular-nums}\n  .ledger .lrow.ok .p{color:var(--green)}\n  .ledger .lrow.warn .p{color:var(--plan)}\n  .ledger .lrow.hot .p{color:var(--red)}\n  .ledger .lrow.unk .p{color:var(--faint)}\n  .ledger .safe{border-top:1px solid var(--line);padding:7px 11px;font-size:12.5px;\n                color:var(--text);background:var(--panel)}\n  .ledger .safe b{font-family:var(--mono);font-variant-numeric:tabular-nums}\n\n  .acard ul{margin:0;padding-left:17px}\n  .acard li{font-size:13.5px;color:var(--muted);margin-bottom:4px}\n  .acard li b{color:var(--text)}\n  .empty{color:var(--muted);font-size:14.5px;background:var(--panel);\n         border:1px dashed var(--line-strong);border-radius:10px;padding:26px;\n         text-align:center;grid-column:1/-1}\n\n  /* ------------------------------------------------------------------ fleet */\n  .fleet{display:grid;grid-template-columns:repeat(auto-fill,minmax(104px,1fr));gap:8px}\n  .tile{display:flex;align-items:center;gap:8px;background:var(--panel);\n        border:1px solid var(--line);border-radius:8px;padding:8px 9px;cursor:pointer;\n        text-align:left;box-shadow:var(--shadow);transition:border-color .12s,transform .12s}\n  .tile:hover{border-color:var(--line-strong);transform:translateY(-1px)}\n  .tile:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n  .tile.sel{border-color:var(--accent);background:var(--accent-bg)}\n  .tile .meta{min-width:0}\n  .tile .lab{font-family:var(--mono);font-size:10.5px;color:var(--muted);\n             white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block}\n  .tile .mrg{font-family:var(--mono);font-size:12px;font-weight:600;\n             font-variant-numeric:tabular-nums;display:block;line-height:1.25}\n  .tile.a0 .mrg{color:var(--faint);font-weight:400}\n  .tile.a1{background:var(--plan-bg);border-color:var(--plan)}\n  .tile.a1 .mrg{color:var(--plan)}\n  .tile.a2{background:var(--tonight-bg);border-color:var(--tonight)}\n  .tile.a2 .mrg{color:var(--tonight)}\n  .tile.a3{background:var(--red-bg);border-color:var(--red)}\n  .tile.a3 .mrg{color:var(--red)}\n\n  /* ----------------------------------------------------------------- detail */\n  .detail{background:var(--panel);border:1px solid var(--line);border-radius:10px;\n          padding:18px 20px;margin-top:16px;box-shadow:var(--shadow)}\n  .detail h3{font-family:var(--disp);font-weight:600;font-size:17px;margin:0 0 3px}\n  .detail .note{color:var(--muted);font-size:13px;margin:0 0 14px}\n  .detail .split{display:grid;grid-template-columns:1fr;gap:18px;align-items:start}\n  @media(min-width:1180px){\n    .detail .split{grid-template-columns:minmax(0,1.5fr) minmax(330px,1fr)}\n  }\n  .chart svg{display:block;width:100%;height:auto;overflow:visible}\n  svg.ico{flex:none;display:inline-block;vertical-align:middle}\n  .axis{display:flex;justify-content:space-between;flex-wrap:wrap;gap:4px 14px;\n        font-family:var(--mono);font-size:10px;color:var(--faint);margin-top:6px}\n  .axis .mid{flex:1;text-align:center;min-width:150px}\n\n.a-1 .verd,.ico.a-1{color:var(--muted)}\n.tile.a-1{border-style:dashed;background:var(--panel2)}\nh2{margin-top:0}.hint{font-size:12px;color:var(--muted)}\n.scope{font-size:12px;color:var(--muted);border-left:3px solid var(--accent);padding:8px 12px;margin-bottom:18px}\n.state{display:inline-block;padding:2px 8px;background:var(--accent-bg);border-radius:5px;font-size:12px}\n.cards{grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr))}\n.ledger .lrow{font-size:12px;align-items:center}.ledger .lrow .p{font-size:11px;text-align:right}\nbody{font-family:Georgia,serif}.chart-gap{color:var(--muted)}\n</style></head><body><div class="wrap"><div class="app">\n<aside class="side">\n<div class="brand">HEAD<span class="chev">&lsaquo;&rsaquo;</span>WAY<small>Time to act</small></div>\n<nav id="nav" aria-label="Views">\n<button class="nav-item" data-view="tonight">Action &amp; review <span class="badge" id="b-tonight"></span></button>\n<button class="nav-item" data-view="fleet">Fleet <span class="badge" id="b-fleet"></span></button>\n<button class="nav-item" data-view="asset">Door detail</button>\n</nav>\n<div class="panelbox"><label class="k" for="day">Telemetry day</label><span class="datebig" id="date"></span>\n<input id="day" type="range" min="0" step="1" aria-label="Replay telemetry day">\n<div class="hint" id="available"></div><div class="row">\n<button class="btn" id="prev" aria-label="Previous day">&larr;</button>\n<button class="btn" id="next" aria-label="Next day">&rarr;</button></div></div>\n<button class="btn" id="theme">Dark theme</button>\n<div class="hint">Demo thresholds: review withdrawal below 1 day; next window below 3 days; plan below 21 days. Confirm policy with the operator.</div>\n</aside><main><div class="scope" id="scope"></div>\n<section id="v-tonight" class="view"><h2>Action &amp; review</h2><p class="sub" id="tonight-sub"></p><div class="cards" id="cards"></div></section>\n<section id="v-fleet" class="view"><h2>Fleet</h2><p class="sub">Filter by action. Unknown data stays visible.</p><div class="filters" id="filters"></div><div class="fleet" id="fleet"></div></section>\n<section id="v-asset" class="view"><h2>Door detail</h2><div id="detail" class="detail"></div></section>\n</main></div></div>\n<script type="application/json" id="payload">__PAYLOAD__</script>\n<script>\nconst DATA=JSON.parse(document.getElementById(\'payload\').textContent),N=DATA.days.length;\nlet day=N-1,selected=null,filter=\'all\',view=\'tonight\';\nconst el=id=>document.getElementById(id);\nconst esc=v=>String(v??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst fmt=v=>Number.isFinite(v)?v.toFixed(1)+\' d\':\'Unavailable\';\nconst states={\'valid\':\'Estimate available\',\'insufficient_history\':\'Insufficient history\',\'insufficient_data\':\'Missing or incomplete data\',\'no_worsening_trend\':\'No worsening trend detected\',\'elevated_no_trend\':\'Elevated signal; countdown unavailable\',\'threshold_exceeded\':\'Threshold exceeded\',\'uncalibrated\':\'Insufficient calibration\',\'outside_horizon\':\'Outside projection horizon\',\'outside_training_conditions\':\'Conditions outside training range\',\'stale_data\':\'Telemetry stale\',\'missing_observation\':\'No observation for this day\'};\nconst label=s=>states[s]||String(s).replaceAll(\'_\',\' \');\nconst held=r=>r.aspect>0&&r.aspect>r.raw;\nfunction head(a){\n const shape=a===-1?\'<text x="7" y="11" text-anchor="middle" fill="currentColor" font-size="12">?</text>\':a===3?\'<polygon points="4,1 10,1 13,4 13,10 10,13 4,13 1,10 1,4" fill="currentColor"/>\':a===2?\'<circle cx="7" cy="7" r="6" fill="currentColor"/>\':a===1?\'<path d="M7 1 A6 6 0 0 1 7 13 Z" fill="currentColor"/><circle cx="7" cy="7" r="6" fill="none" stroke="currentColor"/>\':\'<circle cx="7" cy="7" r="5" fill="none" stroke="currentColor" stroke-width="2"/>\';\n return \'<svg class="ico a\'+a+\'" width="16" height="16" viewBox="0 0 14 14" aria-hidden="true">\'+shape+\'</svg>\';\n}\nconst windowText={within_margin:[\'Within estimated margin\',\'ok\'],exceeds_margin:[\'Exceeds estimated margin\',\'hot\'],no_positive_margin:[\'No positive margin established\',\'warn\'],threshold_exceeded:[\'Threshold exceeded\',\'hot\'],unknown:[\'Cannot assess\',\'unk\']};\nfunction ledger(r){\n const rows=[0,3,7,14,28].map(h=>{\n const [text,color]=windowText[r.windows[String(h)]]||windowText.unknown;\n return \'<div class="lrow \'+color+\'"><span class="w">\'+(h===0?\'Act now\':\'In \'+h+\' days\')+\'</span><span class="p">\'+text+\'</span></div>\';\n }).join(\'\');\n return \'<div class="ledger"><div class="lhd">Maintenance-window comparison</div>\'+rows+\'<div class="safe">Comparison with the estimated lower RUL bound. No individual failure probability is established.</div></div>\';\n}\nfunction card(a){\n const r=a.rows[day],h=held(r);\n return \'<div class="acard a\'+r.aspect+\'"><div class="body"><div class="top"><span class="vwrap">\'+head(r.aspect)+\'<span class="verd">\'+esc(DATA.rec[r.aspect])+\'</span>\'+(h?\'<span class="chip-held">HELD</span>\':\'\')+\'</span><span class="aid">\'+esc(a.id)+\'</span></div><p class="mean">\'+esc(DATA.meaning[r.aspect])+\'</p><p class="state">\'+esc(label(r.state))+\'</p><div class="nums"><div class="cell hero"><span class="k">Estimated lower margin</span><span class="v">\'+fmt(r.margin)+\'</span></div><div class="cell"><span class="k">Decision stability</span><span class="v sm">\'+esc(r.stability)+\'</span></div><div class="cell"><span class="k">Health index</span><span class="v sm">\'+(Number.isFinite(r.hi)?r.hi.toFixed(1):\'Unavailable\')+\'</span></div></div>\'+ledger(r)+\'<ul>\'+(h?\'<li>Earlier escalation retained. Missing data cannot clear it.</li>\':\'\')+r.evidence.map(e=>\'<li>\'+esc(e)+\'</li>\').join(\'\')+\'</ul><p class="hint">Stability measures agreement between point and lower-bound actions, not confidence of being correct.</p><button class="btn" data-open="\'+esc(a.id)+\'">View evidence</button></div></div>\';\n}\nfunction counts(){const c={\'-1\':0,0:0,1:0,2:0,3:0};for(const a of DATA.assets)c[a.rows[day].aspect]++;return c;}\nfunction renderCards(){\n const rows=DATA.assets.filter(a=>a.rows[day].aspect>=2||a.rows[day].aspect===-1);\n rows.sort((a,b)=>b.rows[day].aspect-a.rows[day].aspect);\n el(\'tonight-sub\').textContent=rows.length?rows.length+\' doors need maintenance or evidence review.\':\'No urgent escalation in available telemetry. Review planned work in Fleet.\';\n el(\'cards\').innerHTML=rows.length?rows.map(card).join(\'\'):\'<div class="empty">No urgent action flagged. This is not a guarantee of fault-free operation.</div>\';\n}\nfunction renderFleet(){\n const c=counts(),items=[[\'all\',\'All\',DATA.assets.length],[-1,\'Review data\',c[-1]],[0,\'Monitor\',c[0]],[1,\'Plan\',c[1]],[2,\'Next window\',c[2]],[3,\'Urgent review\',c[3]]];\n el(\'filters\').innerHTML=items.map(([k,t,n])=>\'<button class="chip" data-f="\'+k+\'" aria-pressed="\'+(String(filter)===String(k))+\'"><span class="n">\'+n+\'</span><span class="t">\'+t+\'</span></button>\').join(\'\');\n el(\'fleet\').innerHTML=DATA.assets.filter(a=>filter===\'all\'||a.rows[day].aspect===Number(filter)).map(a=>{\n const r=a.rows[day];\n return \'<button class="tile a\'+r.aspect+\'" data-open="\'+esc(a.id)+\'" aria-label="\'+esc(a.id+\', \'+DATA.rec[r.aspect])+ \'">\'+head(r.aspect)+\'<span class="meta"><span class="mrg">\'+(r.aspect===-1?\'Review data\':r.aspect===0?\'Monitor\':fmt(r.margin))+\'</span><span class="lab">\'+esc(a.id)+\'</span></span></button>\';\n }).join(\'\');\n}\nfunction spark(a){\n const vals=a.rows.map(r=>r.hi),finite=vals.filter(Number.isFinite);\n if(!finite.length)return \'<p class="hint">No valid health observations.</p>\';\n const W=760,H=190,lo=Math.min(0,...finite),hi=Math.max(6,...finite);\n const x=i=>35+i*(W-50)/Math.max(N-1,1),y=v=>H-25-(v-lo)*(H-45)/(hi-lo);\n let path=\'\',pen=false;\n vals.forEach((v,i)=>{if(!Number.isFinite(v)){pen=false;return;}path+=(pen?\'L\':\'M\')+x(i).toFixed(1)+\' \'+y(v).toFixed(1)+\' \';pen=true;});\n const mark=Number.isFinite(vals[day])?\'<circle cx="\'+x(day)+\'" cy="\'+y(vals[day])+\'" r="4" fill="var(--accent)"/>\':\'\';\n return \'<svg viewBox="0 0 \'+W+\' \'+H+\'" role="img" aria-label="Health index; missing observations appear as gaps"><path d="\'+path+\'" fill="none" stroke="var(--accent)" stroke-width="2"/><line x1="\'+x(day)+\'" x2="\'+x(day)+\'" y1="10" y2="\'+(H-20)+\'" stroke="var(--muted)" stroke-dasharray="3 3"/>\'+mark+\'</svg><p class="hint">\'+DATA.days[0]+\' — \'+DATA.days[N-1]+\'. Standardised index; gaps indicate missing observations. The full trajectory is retrospective.</p>\';\n}\nfunction renderDetail(){\n const a=DATA.assets.find(a=>a.id===selected);\n if(!a){el(\'detail\').innerHTML=\'<p>Select a door from Fleet.</p>\';return;}\n const r=a.rows[day], contributions=Object.entries(r.contributions).filter(([,v])=>Number.isFinite(v)).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1]));\n el(\'detail\').innerHTML=\'<h3>\'+esc(a.id)+\'</h3><div class="chart">\'+spark(a)+\'</div>\'+card(a)+\'<p class="hint">Baseline: \'+esc(r.baseline)+\'</p><ul>\'+contributions.map(([k,v])=>\'<li>\'+esc(k.replaceAll(\'_\',\' \'))+\': \'+v.toFixed(2)+\' index contribution</li>\').join(\'\')+\'</ul>\';\n}\nfunction render(){\n el(\'scope\').textContent=DATA.scope;\n el(\'date\').textContent=DATA.days[day];\n const ready=new Date(DATA.days[day]+\'T00:00:00Z\');ready.setUTCDate(ready.getUTCDate()+1);\n el(\'available\').textContent=\'Daily aggregate available \'+ready.toISOString().slice(0,10)+\' at 00:00 SGT\';\n el(\'day\').max=Math.max(N-1,0);el(\'day\').value=day;\n const c=counts();el(\'b-tonight\').textContent=c[-1]+c[2]+c[3];el(\'b-fleet\').textContent=DATA.assets.length;\n for(const v of [\'tonight\',\'fleet\',\'asset\'])el(\'v-\'+v).classList.toggle(\'on\',v===view);\n document.querySelectorAll(\'[data-view]\').forEach(b=>b.setAttribute(\'aria-current\',b.dataset.view===view?\'page\':\'false\'));\n renderCards();renderFleet();renderDetail();\n}\nel(\'day\').addEventListener(\'input\',e=>{day=Number(e.target.value);render();});\nel(\'prev\').onclick=()=>{day=Math.max(0,day-1);render();};el(\'next\').onclick=()=>{day=Math.min(N-1,day+1);render();};\ndocument.addEventListener(\'click\',e=>{\n const b=e.target.closest(\'[data-open]\');if(b){selected=b.dataset.open;view=\'asset\';render();return;}\n const f=e.target.closest(\'[data-f]\');if(f){filter=f.dataset.f;render();return;}\n const nav=e.target.closest(\'[data-view]\');if(nav){view=nav.dataset.view;render();}\n});\nel(\'theme\').onclick=()=>{const dark=document.documentElement.dataset.theme===\'dark\';document.documentElement.dataset.theme=dark?\'light\':\'dark\';el(\'theme\').textContent=dark?\'Dark theme\':\'Light theme\';};\nrender();\n</script></body></html>'

def main():
    df=pd.read_parquet(DATA/"door_deferral.parquet")
    payload=build_payload(df,AspectPolicy())
    selection_path=DATA/"rul_selection.json"
    if selection_path.exists():
        selection=json.loads(selection_path.read_text(encoding="utf-8"))
        if not selection.get("qualified",False):
            payload["scope"] += " No model met all selection criteria; exploratory baseline estimates are shown."
    encoded=json.dumps(payload,separators=(",",":"),allow_nan=False).replace("<","\\u003c")
    OUT.write_text(TEMPLATE.replace("__PAYLOAD__",encoded),encoding="utf-8")
    print(f"Dashboard refreshed: {len(payload['assets'])} doors; explicit unknown states and window comparisons.")
    return 0
if __name__=="__main__": raise SystemExit(main())
